import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { ShieldCheck, User, Zap, Lock, Cpu } from 'lucide-react';

const Login = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({ 
    username: '', 
    role: 'Candidate', 
    skills: '' 
  });
  const [loading, setLoading] = useState(false);

  const handleLogin = (e) => {
    e.preventDefault();
    setLoading(true);

    // Simulate network authentication delay for visual effect
    setTimeout(() => {
      // 1. Save identity to Local Storage
      localStorage.setItem('username', formData.username);
      localStorage.setItem('role', formData.role);
      
      if (formData.role === 'Candidate') {
        localStorage.setItem('skills', formData.skills);
      }

      // 2. Route to the correct dashboard based on role
      if (formData.role === 'Admin') {
        navigate('/admin');
      } else if (formData.role === 'Expert') {
        navigate('/expert');
      } else {
        navigate('/candidate');
      }
    }, 800);
  };

  return (
    <div className="min-h-screen bg-[#020617] flex items-center justify-center p-6 text-white font-sans selection:bg-cyan-500">
      
      {/* Animated Background Glows */}
      <div className="absolute inset-0 overflow-hidden -z-10 flex items-center justify-center">
        <div className="absolute w-[40vw] h-[40vw] bg-cyan-500/20 blur-[120px] rounded-full animate-pulse mix-blend-screen" />
        <div className="absolute w-[30vw] h-[30vw] bg-fuchsia-500/10 blur-[100px] rounded-full mix-blend-screen translate-x-1/2" />
      </div>

      <motion.div 
        initial={{ opacity: 0, y: 30 }} 
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5, ease: "easeOut" }}
        className="w-full max-w-md bg-white/5 border border-white/10 p-10 rounded-[2.5rem] backdrop-blur-2xl shadow-2xl relative overflow-hidden"
      >
        {/* Decorative Top Border */}
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-cyan-400 via-blue-500 to-fuchsia-500" />

        <div className="text-center mb-10">
          <motion.div 
            initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ delay: 0.2, type: "spring" }}
            className="bg-cyan-500/10 w-20 h-20 rounded-2xl flex items-center justify-center mx-auto mb-6 border border-cyan-500/30 shadow-[0_0_30px_-5px_#06b6d4]"
          >
            <ShieldCheck className="text-cyan-400" size={40} />
          </motion.div>
          <h1 className="text-3xl font-black tracking-widest bg-gradient-to-r from-white to-slate-400 bg-clip-text text-transparent uppercase">
            Nexus RAC
          </h1>
          <p className="text-slate-400 mt-2 text-sm tracking-widest uppercase">Identity Verification</p>
        </div>

        <form onSubmit={handleLogin} className="space-y-6">
          
          {/* Role Selection */}
          <div>
            <label className="block text-xs font-bold uppercase tracking-widest text-slate-500 mb-2 ml-1">Access Level</label>
            <div className="relative">
              <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <select 
                className="w-full bg-black/20 border border-white/10 rounded-2xl py-4 pl-12 pr-4 focus:border-cyan-500/50 outline-none appearance-none transition-all cursor-pointer text-white font-bold tracking-wider"
                onChange={(e) => setFormData({...formData, role: e.target.value})}
                value={formData.role}
              >
                <option className="bg-[#0f172a] text-white" value="Candidate">Candidate Assessment</option>
                <option className="bg-[#0f172a] text-white" value="Expert">Expert Panel</option>
                <option className="bg-[#0f172a] text-white" value="Admin">System Admin</option>
              </select>
            </div>
          </div>

          {/* Username Input */}
          <div>
            <label className="block text-xs font-bold uppercase tracking-widest text-slate-500 mb-2 ml-1">Full Name</label>
            <div className="relative group">
              <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-cyan-400 transition-colors" size={18} />
              <input 
                type="text" 
                placeholder="Enter your identity"
                className="w-full bg-black/20 border border-white/10 rounded-2xl py-4 pl-12 pr-4 focus:border-cyan-500/50 outline-none transition-all text-white placeholder:text-slate-600"
                onChange={(e) => setFormData({...formData, username: e.target.value})}
                required
              />
            </div>
          </div>

          {/* Conditional Skills Input (Only shows if Candidate is selected) */}
          <AnimatePresence>
            {formData.role === 'Candidate' && (
              <motion.div 
                initial={{ height: 0, opacity: 0 }} 
                animate={{ height: 'auto', opacity: 1 }} 
                exit={{ height: 0, opacity: 0 }}
                className="overflow-hidden"
              >
                <label className="block text-xs font-bold uppercase tracking-widest text-slate-500 mb-2 ml-1 mt-2">Core Skill Vector</label>
                <div className="relative group">
                  <Cpu className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-cyan-400 transition-colors" size={18} />
                  <input 
                    type="text" 
                    placeholder="e.g., Python, React, AI, MongoDB"
                    className="w-full bg-black/20 border border-white/10 rounded-2xl py-4 pl-12 pr-4 focus:border-cyan-500/50 outline-none transition-all text-white placeholder:text-slate-600"
                    onChange={(e) => setFormData({...formData, skills: e.target.value})}
                    required={formData.role === 'Candidate'}
                  />
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          {/* Submit Button */}
          <button 
            type="submit"
            disabled={loading}
            className="w-full mt-8 py-4 bg-gradient-to-r from-cyan-600 to-blue-600 hover:from-cyan-500 hover:to-blue-500 disabled:opacity-50 text-white font-black tracking-widest uppercase rounded-2xl flex items-center justify-center gap-3 shadow-lg shadow-cyan-900/20 transition-all active:scale-[0.98]"
          >
            {loading ? (
              <div className="w-6 h-6 border-2 border-white border-t-transparent rounded-full animate-spin" />
            ) : (
              <>INITIALIZE SESSION <Zap size={18} className="fill-current" /></>
            )}
          </button>
        </form>
      </motion.div>
    </div>
  );
};

export default Login;
